-- Tracks imported earlier kept their licence beside the artist's name.
UPDATE `music_tracks` SET `license` = substr(`artist`, instr(`artist`, ' · ') + 3), `artist` = substr(`artist`, 1, instr(`artist`, ' · ') - 1) WHERE `license` IS NULL AND `artist` LIKE '% · CC%';
